import pandas as pd

def clean(df):
    df = df.copy()

    for col in ["species", "island", "sex"]:
        if col in df.columns:
            df[col] = df[col].astype("string").str.strip()

    if "sex" in df.columns:
        df["sex"] = df["sex"].str.lower().map({"male": "male", "female": "female"})

    if "island" in df.columns:
        df["island"] = df["island"].replace({
            "Torgerson": "Torgersen",
            "Bisco": "Biscoe"
        })

    if "body_mass_g" in df.columns:
        df["body_mass_g"] = pd.to_numeric(
            df["body_mass_g"].astype("string").str.replace(",", "", regex=False).str.strip(),
            errors="coerce"
        )
        df.loc[
            (df["body_mass_g"] < 2500) | (df["body_mass_g"] > 6500),
            "body_mass_g"
        ] = float("nan")

    return df

def answer(df):
    d = clean(df)
    d = d[d["species"].isin(["Adelie", "Chinstrap", "Gentoo"])]
    d = d.dropna(subset=["species", "body_mass_g"])
    result = d.groupby("species", sort=False)["body_mass_g"].mean()
    return {str(k): float(v) for k, v in result.items()}
